    return`<button class="deck-card" data-archetype="${item.key}"><div class="deck-art"><img class="blur" src="${image}" alt=""><img class="card" src="${image}" alt="${escapeHtml(item.legend)}"></div><div class="deck-copy"><span>TIER ${item.tier} · ${item.domains.join(' / ')}</span><h4>${escapeHtml(item.legend)}</h4><p>${lists} VERIFIED EVENT LIST${lists===1?'':'S'}</p><div class="deck-stats"><span><b>${statLabel(item.share,'%')}</b><small>META SHARE</small></span><span><b>${statLabel(item.win,'%')}</b><small>WIN RATE</small></span><span><b>${statLabel(item.top8)}</b><small>TOP 8s</small></span></div></div></button>`;
